async def _abandon_attempt(
    self, kv: KeyValue, taken: dict[str, int], *, in_flight: str
) -> None:
    """Roll back an acquire attempt that is being abandoned by an exception.

    Runs shielded, so a cancellation of the caller cannot interrupt it.  The
    create that failed may still have reached the server (a timeout on the
    reply), so the in-flight key is checked too.  Anything that cannot be
    deleted stays in ``held`` for :meth:`release_all`.
    """

    async def undo() -> dict[str, int]:
        if in_flight not in taken:
            record, revision = await self._read(kv, in_flight)
            if record is not None and (record.holder, record.run_id) == (
                self._robot,
                self._run_id,
            ):
                taken[in_flight] = revision
        return await self._rollback(kv, taken)

    try:
        leftovers = await asyncio.shield(undo())
    except BaseException:
        leftovers = dict(taken)  # no answer from the bucket: assume nothing was undone
    self._track_leftovers(leftovers)

