// impl implements the Authenticator interface
type impl struct {
	logger          *slog.Logger
	issuerKeyPair   nkeys.KeyPair
	curveKeyPair    nkeys.KeyPair
	userLookup      NatsUserGetter
	validators      ValidatorSource
	sessionResolver SessionResolver
	permResolver    PermissionResolver
	defaultTTL      time.Duration
}

// DefaultTTL is the JWT lifetime for users that do not set one.
const DefaultTTL = time.Hour

// Option customizes an Authenticator.
type Option func(*impl)

// WithPermissionResolver enables users that set permissionsFrom.
func WithPermissionResolver(r PermissionResolver) Option {
	return func(i *impl) { i.permResolver = r }
}

// WithDefaultTTL sets the JWT lifetime for users without their own ttl.
func WithDefaultTTL(ttl time.Duration) Option {
	return func(i *impl) {
		if ttl > 0 {
			i.defaultTTL = ttl
		}
	}
}

// lifetime returns the user's JWT lifetime, falling back to the default.
func (i *impl) lifetime(info *users.UserInfo) time.Duration {
	if info.TTL > 0 {
		return info.TTL
	}
	return i.defaultTTL
}

